//! The Feature inventory, generated by `xtask codegen` (ADR 0072): one
//! generator per source, each reading source files or the types
//! `goodfetch-protocol` emitted in process, joined and sorted by ID.

use std::collections::{BTreeMap, BTreeSet};
use std::path::Path;

use anyhow::Result;
use goodfetch_protocol::catalog::Product;
use serde_json::Value;

use super::command::CommandLines;
use super::entry::{Carriers, unreadable};
use super::files::{self, AreasFile, Feature, Inventory};
use super::{command, contract, format, row, shared_type, skill, story};

/// ADR 0087's generated table of the names only Foxhound carries, by catalog
/// section.
pub(crate) type FoxhoundNames = BTreeMap<String, BTreeSet<String>>;

/// What the generators read besides the workspace's files.
pub(crate) struct Sources<'a> {
    /// The workspace's folder.
    pub(crate) root: &'a Path,
    /// The catalog file, as emitted.
    pub(crate) catalog: &'a Value,
    /// The JSON Schema bundle, as emitted.
    pub(crate) bundle: &'a Value,
    /// The names only Foxhound carries.
    pub(crate) foxhound_names: &'a FoxhoundNames,
    /// Both executables' command lines; none when the workspace has no
    /// executable crate.
    pub(crate) command_lines: Option<&'a CommandLines>,
}

pub(crate) fn generate(sources: &Sources<'_>) -> Result<Inventory> {
    let areas: AreasFile = files::read_optional_toml(sources.root, files::AREAS)
        .map_err(|error| unreadable(error, files::AREAS))?;
    let mut entries = story::entries(sources.root)?;
    entries.extend(row::entries(sources.root)?);
    entries.extend(contract::entries(sources.catalog));
    entries.extend(format::entries(sources.bundle));
    entries.extend(command::entries(sources.command_lines));
    entries.extend(shared_type::entries(sources.catalog));
    entries.extend(skill::entries(sources.root)?);
    let mut features: Vec<Feature> = entries
        .into_iter()
        .map(|entry| {
            let area = entry
                .area
                .or_else(|| match areas.owners(entry.kind, &entry.name)[..] {
                    [area] => Some(area),
                    _ => None,
                });
            let foxhound_only = match entry.carriers {
                Carriers::Both => false,
                Carriers::Foxhound => true,
                Carriers::Table(section) => sources
                    .foxhound_names
                    .get(section)
                    .is_some_and(|names| names.contains(&entry.name)),
            };
            Feature {
                id: format!("{}:{}", entry.kind, entry.name),
                kind: entry.kind,
                area,
                milestone: entry.milestone,
                status: entry.status,
                products: if foxhound_only {
                    vec![Product::Foxhound]
                } else {
                    vec![Product::Collie, Product::Foxhound]
                },
            }
        })
        .collect();
    features.sort_by(|left, right| left.id.cmp(&right.id));
    Ok(Inventory { features })
}
